  "duration": "2分02秒",
  "perspective": "分析视角：单指标考核的扭曲机制与对冲解法",
  "url": "local:01e46cdadc40a43a01037103884d85473b_4610.mp4video.MP4",
  "summary": "核心判断：每一个 KPI 背后都有一个复仇女神——你考核什么，人们就扭曲什么来达标。只设销售额一个指标，销售就会亏本卖货冲业绩。解法是让 KPI 互相牵制对冲，组成指标系统；否则单指标漏洞会被聪明人利用，把烂摊子留给公司。",
