    "body": "在讲什么：高度 = 既能在事情里面看细节，也能抽象到事情上面看脉络、性质和联系。房子类比：站在房间里只能看到房间；俯视时能看到花园、旁边的房间和楼。决定房子好不好的是环境、安保、空气、停车位。关键理解：评价事情好坏要站在更高维度。怎么用：答辩时展示你对外延（上下游、竞品、公司战略）的思考。",
    "quote": "依据 [00:26–01:15]：我在事情上面看，会看到整个事情的脉络……我站在房间上面往下俯视的时候，可以看到花园，可以看到旁边的房间，看到这个楼旁边的楼。",
