    "title": "原则：成年人学习以鼓励为主",
    "body": "在讲什么：成年人学习不应该也不能够被否定，应以鼓励为主。你面对的是抬头不见低头见的同事；更深一层，你的目标是收获粉丝、建立信任，让大家愿意跟着你干。哪怕学员没掌握内容，只要相信你、愿意跟着你干，课就是成功的。关键理解：反馈服务于关系而非对错。怎么用：把「教对」的目标换成「建立信任」的目标。",
    "quote": "依据 [00:42–01:18]：你的目标是收获粉丝、建立信任，让大家愿意跟着你干。哪怕你上完课，人家对你讲的内容没有掌握，但人家听完课以后相信你、愿意跟着你干，那你的课就是成功的。",
