    "title": "透明动了利益链",
    "body": "在讲什么：传统企业工资低，基层要从关系、采购、运输、生产、销售每个环节的预算和购买关系里捞好处。不透明才是他们生存赚钱的原因，透明了大家都没利益可拿。大老板要搞数字化反这些东西。关键理解：数字化是利益再分配。怎么用：进入前先看清谁的利益会被动。",
    "quote": "依据 [00:05–00:37]：传统企业里面最多的就是利益链，不透明才是他们能生存赚钱的原因，透明了大家都没有利益可拿。",
