    "body": "在讲什么：很多人幻想「我是块石头，那个地方正好需要石头，我就能去」，这个想法很幼稚——天下石头多的是，外面还有一堆，老板没必要非找你。你不说，老板只能猜，可老板选择多、有权利，你让他猜就是吃亏。关键理解：机会不是被需要的巧合，是你主动做局的结果。怎么用：主动大胆表达意愿，别等着被看见。",
    "quote": "依据 [00:00–00:08]：很多东西要天时地利人和，你自己要做局，你不要幻想好像就是说，我是个石头，那个地方好像需要块石头，我就可以去，这想法贼幼稚。",
