    "body": "在讲什么：相亲时你只能看到颜值、资产存量、家庭背景三样东西，但认知水平看不见，它却是综合打分里权重最高的一项——能不能让你过上美好的新生活就靠它。关键理解：看得见的都是存量，看不见的认知才是增量，也是最大的风险项。怎么用：别急着打分，先把认知水平这个变量套出来。",
