   {
    "tone": "card-orange",
    "title": "视觉有心理重量，构图就是配重",
    "body": "在讲什么：视觉是有心理重量的——画面会左中右倾，在右边放置一个物体就能找回视觉的平衡。对画面做这种配重设计的过程，就是构图。关键理解：构图不是摆得好看，而是用元素的位置和大小控制画面重心。怎么用：拍完先看画面往哪边倾，再决定把配重物放哪里。",
    "quote": "依据 [00:42–00:56]：但视觉是有心理重量的，比如这样的画面会左中右倾，在右边放置一个物体就会找回视觉的平衡。这样对画面的设计的过程被称为构图。",
    "relation": "立场分层：心理重量为讲者核心概念；左倾右放物为演示例子。"
   },
   {
    "tone": "card-purple",
    "title": "构图的本质：抓结构配重，少即是多",
    "body": "在讲什么：构图最重要的是结构——画面的线条就是照片的结构，合理抓取画面结构的配重比例，用最少的元素交代最全面的现实场景，是深入摄影的高级修炼。关键理解：元素不是越多越好，配重对、结构清，少也能说全。怎么用：每次构图都问一句——这个元素是必须的吗？删掉它视线还完整吗？",
    "quote": "依据 [01:04–01:13]：画面的线条就是照片的结构，合理地抓取画面的结构的配重比例，用最少的元素，交代最全面的现实场景，是深入摄影时期高级的修炼。",
    "relation": "立场分层：结构配重为讲者方法论；「少元素多场景」为其价值判断。"
   }
