    "body": "在讲什么：无风险收益 2.3%-2.4%，从 2.3% 加两个点做到 4.3% 要冒很大风险；顶级的基金经理和最差的基金经理长线收益就差两个点，500万的两个点是 10 万块，用心理财的人一年最多只比存银行多赚 10 万。关键理解：两个点已经足以区分基金经理的段位，普通人的超额收益空间非常有限。怎么用：评估任何理财投入时，先把「多赚的钱」折成绝对值再决策。",
    "quote": "依据 [00:16-00:54]：我从2.3%的基础上加两个点，我做到4.3%，你需要冒多大的风险？……500万的两个点是多少钱？10万块。",
