  "boundary": [
   "适用：讲解型 PPT 中的并列结构要点页（几点原因、几个要点），以及需要听众记住内容的汇报场景。",
   "上限：不适用于必须给出明确结论、一步接一步的流程或操作演示。",
   "反例：内容之间有严格逻辑依赖时，强行要求排序反而会让听众困惑。",
   "例外：提问后必须真的停顿等待回应；场合不允许互动（如超时汇报）时不适用。"
  ],
  "pitfalls": [
   "避坑：提问后必须真的停顿等待，连续自问自答就失去了「让听众思考」的意义。",
   "避坑：排序问题只适合并列、可比的内容，逻辑链上的内容硬套会适得其反。",
   "避坑：挑逗群众要有分寸——对老板、客户汇报时适度收敛，避免显得不严肃。"
  ],
