 "side-business-prerequisites": {
  "title": "搞副业前先问自己：三个前提都满足了吗",
  "tags": [
   "职场",
   "副业",
   "方法论"
  ],
  "duration": "1分52秒",
  "perspective": "分析视角：副业启动前的三个前提条件检验",
  "url": "local:01e50971131b1cf5010371038aace395b6_258.MP4",
  "summary": "核心判断：副业不是「想搞就能搞」，启动前必须过三关——主业无敌（主业已无可难到你）、时间复用（副业时间直接反哺主业）、激励相容（副业与主业互相促进成飞轮）。三关都能在纸面上推导成闭环，才谈得上开始；否则副业大概率演变成把主业一起搞没的悲剧。",
  "timeline": [
   [
    "00:00",
    "副业悲剧开场：还没赚钱，主业先没了"
   ],
   [
    "00:10",
    "就业环境差，先感恩、端好饭碗"
   ],
   [
    "00:18",
    "三个前提，仔细听完再动手"
   ],
   [
    "00:26",
    "前提一：主业无敌才能搞副业"
   ],
   [
    "00:40",
    "别低估羡慕嫉妒的破坏力，会有人打小报告"
   ],
   [
    "00:52",
    "前提二：时间复用，等于下班还在为公司工作"
   ],
   [
    "01:02",
    "前提三：激励相容，互相促进成飞轮"
   ],
   [
    "01:11",
    "个人例子：一个人拍视频，就是一支队伍"
   ],
   [
    "01:35",
    "主业的坑和苦，都是副业变现的资产"
   ],
   [
    "01:52",
    "纸面推导无逻辑漏洞，才能开始"
   ]
  ],
  "map": [
   [
    "现象",
    "副业搞着搞着，把主业搞没了"
   ],
   [
    "拆穿",
    "副业比想象中难，占用时间藏不住"
   ],
   [
    "真相",
    "需要主业无敌、时间复用、激励相容"
   ],
   [
    "行动",
    "纸面推导出逻辑闭环后再开始"
   ]
  ],
  "corrections": [
   "误解1：搞副业要趁早、先干起来再说。纠偏：动手前先检验三个前提，否则有把主业搞丢的风险。",
   "误解2：副业偷偷做就行，不影响主业。纠偏：副业必占时间、藏不住，要时间复用，让副业时间反哺主业。",
   "误解3：副业和主业是竞争关系。纠偏：好的副业与主业激励相容、互相促进，形成飞轮效应。"
  ],
  "cards": [
   {
    "tone": "card-green",
    "title": "前提一：主业无敌，才不怕打小报告",
    "body": "在讲什么：主业已经没什么能难到你，同事的业务难题你马上能给方案，所有人都服气。关键理解：主业不硬，副业很容易被有心人举报，你低估了羡慕嫉妒的破坏力。怎么用：把主业打磨到无可挑剔，再谈副业。",
    "quote": "依据 [00:26-00:45]：如果不满足，你搞的副业总会有人知道，别人会对你不服气打小报告，你不能低估羡慕嫉妒的破坏力。",
    "relation": "立场分层：「主业无敌」是前提；「防打小报告」是现实理由。"
   },
   {
    "tone": "card-orange",
    "title": "前提二：时间复用，反哺主业",
    "body": "在讲什么：你花在副业上的时间，都可以给主业带来直接结果和好处，等于下班后还在为公司工作。关键理解：时间复用让副业不消耗主业，反而增值。怎么用：选择与主业技能相关、能互相借力的副业方向。",
    "quote": "依据 [00:52-01:01]：你花在副业上的所有时间，都是可以给你主业带来直接的结果和好处的。",
    "relation": "立场分层：「时间复用」是定义；「选择相关副业」是落地选择。"
   },
   {
    "tone": "card-purple",
    "title": "前提三：激励相容，形成飞轮",
    "body": "在讲什么：副业搞好了促进主业，主业搞好了反过来促进副业，互相促进形成飞轮效应。关键理解：副业与主业应是正循环，而不是零和博弈。怎么用：用例子检验——公司要拍宣传片，一个人就能搞定，省下的成本就是副业反哺主业的证据。",
    "quote": "依据 [01:02-01:38]：副业搞好了就能促进主业，主业搞好了又能反过来促进副业，互相促进，形成飞轮效应。",
    "relation": "立场分层：「激励相容」是抽象原则；「一人团队拍视频」是具体例证。"
   }
  ],
  "table": {
   "title": "搞副业的三前提对照表",
   "head": [
    "前提",
    "含义",
    "检验问题"
   ],
   "rows": [
    [
     "主业无敌",
     "主业已无可难到你，同事都服气",
     "我的主业还有解决不了的难题吗？"
    ],
    [
     "时间复用",
     "副业时间直接反哺主业",
     "副业时间能给主业带来结果吗？"
    ],
    [
     "激励相容",
     "副业与主业互相促进",
     "两者能形成正循环飞轮吗？"
    ]
   ]
  },
  "boundary": [
   "适用：有稳定主业、想发展副业的职场人启动前的自检清单。",
   "上限：不保证副业成功，只排除把主业搞丢的显性风险。",
   "反例：主业不稳定、还靠补贴维持时，先别谈副业。",
   "例外：极少数人的副业与主业完全无关也能成立，但仍需时间与精力自洽。"
  ],
  "pitfalls": [
   "避坑：把「主业无敌」当成自我感觉良好，要用同事真的来请教验证。",
   "避坑：时间复用不等于下班继续干活，要量化副业时间的主业产出。",
   "避坑：飞轮效应不会自然发生，要先设计主副业之间的输入输出关系。"
  ],
  "conclusion": {
   "key": [
    "搞副业前先过三关：主业无敌、时间复用、激励相容。",
    "副业必占时间、藏不住，要让时间反哺主业。",
    "先在纸面上推导成逻辑闭环，再开始搞。"
   ],
   "actions": [
    "自检主业：还有没有同事来请教的难题？",
    "为副业设计一条「反哺主业」的时间路径。",
    "把主副业的互相促进关系写成一张逻辑图再评估。"
   ],
   "shift": "从「副业=另一份赚钱的事」转到「副业=与主业互相赋能的系统」：先论证逻辑闭环，再投入时间，避免副业与主业双输。"
  },
  "footer_duration": "1分52秒"
 }
