  "url": "local:RPReplay_Final1686669776(1).MP4",
  "summary": "核心判断：竞业协议是公司保护商业利益的枷锁，正在从高管扩散到全员。对它要分三档处理——入职时能拒签最好；岗位关键敏感就老老实实履行，因为违约代价是补偿金的 N 倍；而公司三个月不发补偿金时，劳动者反而可以书面解除并申请劳动仲裁，从「被锁住」转为「主动出锁」。",
