    "tone": "card-purple",
    "title": "两条出路：躲不过，但可以主动解",
    "body": "在讲什么：换马甲（换身份、挂靠第三方）躲不过，圈子就这么大；真正的出路是——公司三个月没付补偿金，保留证据、书面解除、申请劳动仲裁。关键理解：竞业协议是双向的，企业不履行补偿义务，你的义务也失去基础。怎么用：记录好补偿金发放节点，欠费三个月就启动解除流程。",
