  "summary": "核心判断：35 岁求职难是定位困境、职场偏见与投入担忧三重因素叠加的结果，而非单纯年龄问题。破局不靠焦虑，靠五个动作：调整心态、改变渠道、降低预期、换行业赛道、打磨简历厚度——把年龄局限转化成经验厚度与职业成熟度的筹码。",
