  "url": "local:RPReplay_Final1686667887(1).MOV",
  "summary": "核心判断：工作没劲、成长停滞，往往是因为跟错了领导。面试既是公司面你，也是你面公司——用「尊重、专业、开放、激情」四把尺子量未来领导：尊重看面试体验，专业看观点深度，开放看是否接纳建议，激情看讲业务时眼睛是否放光。四点越齐全，越值得跟随。",
