  "summary": "核心判断：找不到满意 offer 时，仓促将就通常不是好选择——将就可能导致恶性循环或放弃求职初心；但一味硬撑也不对。正确做法是用「求职周期 × 投入度」校准：一般岗位 1-3 个月求职周期内全力以赴仍无满意 offer，说明目标与实际差异太大，该调整目标而非无脑坚持或无脑将就。",
