   "误解 2：既然将就不好，那就无限期坚持等满意 offer。纠偏：一味坚持会脱离实际，要用求职周期和投入度校准目标。",
   "误解 3：求职只要努力就一定能在期限内找到满意工作。纠偏：求职还受运气影响，目标与实际差异太大时要调整目标。"
