    "body": "在讲什么：和而不同是我与这个世界怎么打交道的问题；世界不仅是我一个人，有太多万事万物。关键理解：尊重差异、接纳万物，是中国智慧的相处之道。怎么用：与人合作时先看见差异，再求同存异。",
    "quote": "依据 [00:00-00:20]：和而不同，实际上是我与世界怎么打交道、怎么与这个世界相处……这个世界不仅是我一个人，有太多的万事万物。",
