   "误解2：所有影调参数都是整体提亮变暗。纠偏：黑色、阴影、高光、白色分别影响不同亮度区间，各有侧重。",
   "误解3：对比度就是「拉高让画面更鲜艳」。纠偏：对比度以中性灰为界限，提对比让亮更亮、暗更暗。"
