  "summary": "核心判断：创业者的一天是一天十几个小时跑客户、联系业务、做技术储备；现在的讲者每天走一万步，不是换了一种活法，而是人生阶段和事业阶段不同了——拼的时间太长，拼不住了。他明确说：不后悔，回到当时还会那么拼；如果今天再回公司主导，从头到尾还是得那么做。给年轻人的提醒是：不要把他现在的状态当成创业常态。",
