    "quote": "依据 [00:14-00:26]：任何年轻人、创业者看到我现在这样状态不要以为是常态……那个才是公司的常态，我只不过是我拼的时间太长，是拼不住了。",
    "relation": "立场分层：「拼命才是常态」为对创业的如实描述；「拼不住了」为讲者切换节奏的个人原因。"
