  "summary": "核心判断：不生孩子未必是缺憾——讲者不觉得这是件大事情，但也不回避「衰弱时无至亲陪伴」的现实。面对「再选一次是否做母亲」的问题，她给出的答案是领养：身体好的话去领养几个孩子。因为传承不等于基因，自己的基因不比别人好，用善意和温暖去滋养生命，是同样成立、甚至更成立的传承方式。",
