    "title": "绝望的人：剩下的路",
    "body": "在讲什么：讲者看到年轻人相约自杀非常难受，能体会到那种绝望——没有希望、没有未来、没有钱，心里又无法抵抗时，剩下的路就是抑郁或自杀。关键理解：绝望是现实压力叠加心理失守的结果，不是脆弱。怎么用：别用「至于吗」评判，那是求救信号，需要的是被看见和实际支持。",
    "quote": "依据 [00:46-00:57]：觉得自己没有希望、没有未来、没有钱，心里又不能足够地抵抗的话，那剩下的路就是抑郁或者自杀了。",
    "relation": "立场分层：「能体会到绝望」为共情；「希望/未来/钱的缺失＋心理失守」为对绝望成因的归因。"
