  "summary": "核心判断：面试自我感觉一般却通过，背后是面试官视角的三种逻辑——招人难导致门槛降低、自我感觉与真实表现错位、表现恰好匹配岗位需求。别用自己的感觉否定自己，通过与否取决于对方需求与你的匹配度。",
