    "tone": "card-orange",
    "title": "无背调支持：弱化聚焦",
    "body": "在讲什么：前主管不支持背调，就只能实话实说，但要弱化被辞退的原因，把重点放在教训、弥补措施（培训充电）与已取得的进步上，并表达对岗位的信心。关键理解：实话实说不等于全盘交代，要说有选择的话。怎么用：提前把「教训+弥补+进步」讲成故事，面试时主动引导。",
    "quote": "依据 [00:27-00:34]：我们只能实话实说，但是一定要有选择的说，弱化被辞退的原因，把重点放在通过这件事你得到了什么样的教训，之后做了哪些弥补措施。",
    "relation": "立场分层：弱化聚焦为沟通策略；「教训与弥补」是给出的内容框架。"
