  "summary": "核心判断：多数跳槽由情绪冲动驱动（同事矛盾、被领导批评），而不是因为下一份工作更好。跳槽前用四个问题校准自己：是否真没成长空间、能力是否真无法提升、岗位是否真无可替代、现状是否真触底。四个问题答完再决定，把冲动变成判断。",
