    "quote": "依据 [00:13-00:33]：在跳槽之前，先问自己四个问题：你在这份工作中真的没有成长空间了吗？你的能力真的已经无法提升了吗？你在这个岗位上真的已经无可替代了吗？你的现状真的已经触底、无法改善了吗？",
