  "summary": "核心判断：生病时对前半生的怀疑，本质是「太虚弱带来的头脑不坚定」，不是真实的判断。讲者想通了一个等式：如果有个孩子就所有问题都解决，那世界也太简单了——问题不是出在没有孩子，而是出在把希望都寄托在某个身份上。真正重要的感情是能相见、能相望于江湖、能天天陪着你的人，你管他是儿子、女儿还是谁。",
