    "title": "怀疑来自虚弱，不是真相",
    "body": "在讲什么：生病时怀疑前半生做错了、努力白费了、生个娃就算成功——但怀疑的根源是太虚弱带来的头脑不坚定。关键理解：低谷期的自我否定，往往是身体状态的投射。怎么用：在虚弱时不做人生总结，等状态恢复再下判断。",
    "quote": "依据 [00:15-00:24]：我当时生一个娃那我就成功了，我真的怀疑过，因为你太虚弱了，会带来头脑的不坚定。",
