    "quote": "依据 [00:34-00:43]：那什么样的感情重要？那就是既能相见，又能相望于江湖的；然后他能够天天陪你的，你管他是不是你的儿子、是不是你的女儿、是不是你的谁。",
    "relation": "立场分层：「既相见又相忘于江湖」为理想关系形态；「能天天陪你」为对这一形态的现实化解释。"
