   "误解 2：选亲密关系还是选事业，是个二选一的统一答案。纠偏：答案因人而异，取决于各自的使命与舒适区。",
   "误解 3：不擅长带娃就是不负责。纠偏：讲者正是意识到自己当妈妈会「不负责」，才选择了更适合自己的路，这是负责。"
