    "quote": "依据 [00:52-00:59]：如果我是一个妈妈的话，在别人眼里恐怕不是一个太负责任的妈妈。所以我就坐着坐着（走着走着），我就做成这样了。",
    "relation": "立场分层：「当妈妈会不负责」为自我评估；「走成现在这样」为由此选择的路径。"
