  "url": "local:RPReplay_Final1686364327(1).MOV",
  "summary": "核心判断：「管人还是管事」是伪问题。真正的管理目标导向、以事为先，但「事」分层次——高层管宏观方向、中层管战略落地目标、一线管具体事，错位就陷入概念聊天。人手路径按资源选：有钱招精英就靠筛选和授权，没钱培养普通人就靠 SOP 与培训。中层还要向上管理、建信息管道、上下打通，带着大家打胜仗。",
