    "body": "在讲什么：公司成立是为了做事，商业目标是非常具体的事；组织是关于人的，但一定建立在事情之上。关键理解：管人还是管事之争是伪问题，事情的结果才是检验标准。怎么用：管理动作从目标出发，再设计组织与人的配合。",
    "quote": "依据 [00:10-00:55]：你事没做好，只是把人管好了，这个结果你拿到了吗？……组织是关于人的，但是一定是建立在事情之上。",
